// NLE-007: Server error on /product/4
// Generated by Nomad Loop Engine. Run: npx playwright test nle-007.spec.ts
import { test, expect } from '@playwright/test';

test("NLE-007: Server error on /product/4", async ({ page }) => {
  const errors: string[] = [];
  const failed: string[] = [];
  const docStatuses: number[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('response', (res) => {
    if (res.request().isNavigationRequest()) docStatuses.push(res.status());
    else if (res.status() >= 400) failed.push(`${res.status()} ${res.url()}`);
  });
  await page.goto("http://localhost:4100/product/4");
  expect(docStatuses.every((s) => s < 400), `document statuses: ${docStatuses}`).toBe(true);
});
